 public static void Run(){byte[] parameters=new byte[0x25A];parameters[0x163]=60;parameters[0x259]=8;parameters[0x15F]=128;parameters[0x160]=1;bool[] all=StatusSusceptibility.Flags(parameters);for(int i=0;i<7;i++)Check(all[i],"All seven disable flags decode");parameters[0x163]=16;parameters[0x259]=0;parameters[0x15F]=0;parameters[0x160]=0;bool[] bleed=StatusSusceptibility.Flags(parameters);for(int i=0;i<7;i++)Check(bleed[i]==(i==2),"Bleed flag independent");var s=new EnemySnapshot{StatusBlocked=bleed,BaseStatus=new[]{100,100,100,999,100,100,999},Thresholds=new[]{200,200,200,999,200,200,2015}};Check(StatusSusceptibility.State(s,0)=="Yes","Confirmed positive susceptibility");Check(StatusSusceptibility.State(s,2)=="Immune","Explicit bleed immunity");Check(StatusSusceptibility.State(s,6)=="Unknown","High threshold not assumed immune");Check(StatusSusceptibility.State(new EnemySnapshot(),0)=="Unknown","Missing data not guessed");long actor=0x10000,effects=0x20000,node=0x30000,param=0x40000;var mem=new Dictionary<long,byte[]>{{actor+0x178,BitConverter.GetBytes(effects)},{effects+0x10,BitConverter.GetBytes(actor)},{effects+8,BitConverter.GetBytes(node)},{node,new byte[0x40]},{param,parameters}};Array.Copy(BitConverter.GetBytes(param),mem[node],8);Array.Copy(BitConverter.GetBytes(123),0,mem[node],8,4);Func<long,int,byte[]> read=(a,n)=>mem[a];Check(StatusSusceptibility.Read(actor,read)[2],"Active effect list immunity");mem[effects+0x10]=BitConverter.GetBytes(actor+8);Reject(()=>StatusSusceptibility.Read(actor,read),"Wrong effect owner rejected");mem[effects+0x10]=BitConverter.GetBytes(actor);Array.Copy(BitConverter.GetBytes(node),0,mem[node],0x30,8);Reject(()=>StatusSusceptibility.Read(actor,read),"Effect cycle rejected");Array.Copy(BitConverter.GetBytes((long)0),0,mem[node],0x30,8);int reads=0;Reject(()=>StatusSusceptibility.Read(actor,(a,n)=>{if(a==node&&++reads==2){var changed=(byte[])mem[node].Clone();changed[8]++;return changed;}return read(a,n);}),"Changing effect rejected");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"status-test-results.txt"),"PASS: seven immunity bits, independent bleed flag, Yes/Immune/Unknown classification, active effect list, invalid owner/cycle/change rejection. Mock memory only; live susceptibility access needs verification.");}
